window.docContents[240].resolve({"/Terms/#Cvc___lean----High-Level-API-for-CVC5--Terms--Untyped-Terms--Examples":{"contents":"Below is the untyped version of the first typed-term example. No type-inference can take place, so\nwe must always specify what the sort of each symbol is.\n\nopen Untyped in #eval Env.runIO do\n  -- specify the sort using Lean types...\n  let b1 ← Term.mkSymbolAs Bool \"b1\"\n  -- ...or using `Srt` values\n  let bool ← Srt.bool\n  let b2 ← Term.mkSymbol bool \"b2\"\n  let conj ← b1.and b2\n  println! \"conj := {conj}\"\n  let i1 ← Term.mkSymbolAs Int \"i1\"\n  let zero ← Term.mkInt 0\n  let i1_pos ← zero.le i1\n  println! \"i1_pos := {i1_pos}\"\n  let i2 ← Term.mkSymbolAs Int \"i2\"\n  let ite ← i1_pos.ite i1 i2\n  println! \"ite := {ite}\"\n\n\nconj := (and b1 b2)\ni1_pos := (<= 0 i1)\nite := (ite (<= 0 i1) i1 i2)\n\n\n-- using the `smt!` extension\nopen Untyped in #eval Env.runIO do\n  let b1 ← Term.mkSymbolAs Bool \"b1\"\n  let b2 ← Term.mkSymbolAs Bool \"b2\"\n  let conj ← smt! b1 ∧ b2\n  println! \"conj := {conj}\"\n  let i1 ← Term.mkSymbolAs Int \"i1\"\n  let i1_pos ← smt! 0 ≤ i1\n  println! \"i1_pos := {i1_pos}\"\n  let i2 ← Term.mkSymbolAs Int \"i2\"\n  let ite ← smt! if 0 ≤ i1 then i1 else i2\n  println! \"ite := {ite}\"\n\n\nOn functions:\n\nopen Untyped in #eval Env.runIO do\n  let f ← Term.mkSymbolAs (Int → Bool → Int) \"f\"\n  println! \"f : {← f.getSort} := {f}\"\n  let i ← Term.mkSymbolAs Int \"i\"\n  let f_i ← f.apply i\n  println! \"f_i : {← f_i.getSort} := {f_i}\"\n  let b ← Term.mkSymbolAs Bool \"b\"\n  let f_i_b ← f_i.apply b\n  println! \"f_i_b : {← f_i_b.getSort} := {f_i_b}\"\n  -- alternatively\n  let f_i_b' ← f.apply2 i b\n  println! \"f_i_b' : {← f_i_b'.getSort} := {f_i_b'}\"\n\n\nf : (-> Int Bool Int) := f\nf_i : (-> Bool Int) := (f i)\nf_i_b : Int := (f i b)\nf_i_b' : Int := (f i b)\n\n\n-- using the `smt!` extension\nopen Untyped in #eval Env.runIO do\n  let f ← Term.mkSymbolAs (Int → Bool → Int) \"f\"\n  let i ← Term.mkSymbolAs Int \"i\"\n  let f_i ← smt! f i\n  println! \"f_i := {f_i}\"\n  let b ← Term.mkSymbolAs Bool \"b\"\n  let f_i_b ← smt! f_i b\n  println! \"f_i_b := {f_i_b}\"\n\n  let f_i_b' ← smt! f i b\n  println! \"f_i_b' := {f_i_b'}\"\n\n\nSince no type-checking is taking place, we can compile invalid terms without issue.\n\nsection variable [Ω] open Untyped\ndef badTerms : Env Unit := do\n  let b1 ← Term.mkSymbolAs Bool \"b1\"\n  let b2 ← Term.mkSymbolAs Int \"b2\"\n  let conj ← b1.and b2\n  println! \"conj := {conj}\"\nend\n\n\nRunning that code fails with a relatively obscure error.\n\n#eval Env.runIO badTerms\n\n\n[internal] expecting a Boolean subexpression\n\n\n","context":"Cvc.lean -- High-Level API for CVC5\u0009Terms\u0009Untyped Terms","header":"4.2.1. Examples","id":"/Terms/#Cvc___lean----High-Level-API-for-CVC5--Terms--Untyped-Terms--Examples"}});